/* 裸机 vs RTOS

裸机(前后台系统)：
  while(1) {
    task1();
    task2();
    task3();
  }
  中断 → 后台
  缺点：任务互相阻塞

RTOS：
  task1() { while(1){...} }
  task2() { while(1){...} }
  task3() { while(1){...} }
  调度器自动切换
  优点：高优先级及时响应

RTOS特性：
  - 抢占式调度
  - 优先级
  - 任务间通信
  - 确定性响应
*/

// 任务函数
void LEDTask(void* argument) {
    while (1) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
        vTaskDelay(500);  // 延时500ms
    }
}

// 创建任务
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    // 方法1：FreeRTOS原生
    xTaskCreate(LEDTask, "LED", 128, NULL, 3, NULL);

    // 方法2：CMSIS-OS封装
    osThreadDef(LED, LEDTask, 3, 0, 128);
    osThreadCreate(osThread(LED), NULL);

    vTaskStartScheduler();
    while (1);
}

// CubeMX生成的任务框架
void StartLEDTask(void const * argument) {
    /* USER CODE BEGIN StartLEDTask */
    while (1) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
        osDelay(500);  // CMSIS-OS延时
    }
    /* USER CODE END StartLEDTask */
}

// 带参数的任务
void PrintTask(void* arg) {
    char* name = (char*)arg;
    while (1) {
        printf("%s running\r\n", name);
        vTaskDelay(1000);
    }
}

char* name = "Task1";
xTaskCreate(PrintTask, "Print", 256, name, 2, NULL);

// vTaskDelay用法
void task1(void* arg) {
    while (1) {
        // 延时500ms
        vTaskDelay(500);  // 或 osDelay(500)
        // 延时1秒
        vTaskDelay(pdMS_TO_TICKS(1000));  // 毫秒转tick
    }
}

// 绝对延时(精确周期)
void periodicTask(void* arg) {
    TickType_t lastWake = xTaskGetTickCount();
    while (1) {
        // 每100ms精确执行一次
        vTaskDelayUntil(&lastWake, pdMS_TO_TICKS(100));
        doSomething();
    }
}

// 多任务LED控制
void LED1Task(void* arg) {
    while (1) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
        vTaskDelay(500);  // 500ms
    }
}

void LED2Task(void* arg) {
    while (1) {
        HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);
        vTaskDelay(200);  // 200ms
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    xTaskCreate(LED1Task, "LED1", 128, NULL, 2, NULL);
    xTaskCreate(LED2Task, "LED2", 128, NULL, 2, NULL);

    vTaskStartScheduler();
    while (1);
}

// 通过参数复用任务
typedef struct {
    GPIO_TypeDef* port;
    uint16_t pin;
    int delay;
} LED_Config;

LED_Config led1 = {GPIOC, GPIO_PIN_13, 500};
LED_Config led2 = {GPIOA, GPIO_PIN_5, 200};

void LEDTask(void* arg) {
    LED_Config* cfg = (LED_Config*)arg;
    while (1) {
        HAL_GPIO_TogglePin(cfg->port, cfg->pin);
        vTaskDelay(cfg->delay);
    }
}

// 创建
xTaskCreate(LEDTask, "LED1", 128, &led1, 2, NULL);
xTaskCreate(LEDTask, "LED2", 128, &led2, 2, NULL);

// 综合示例：多任务系统
#include "main.h"

void SensorTask(void* arg) {
    while (1) {
        // 读取传感器
        float temp = readTemp();
        // 存储到全局或队列
        g_temp = temp;
        vTaskDelay(2000);  // 2秒
    }
}

void DisplayTask(void* arg) {
    while (1) {
        // 显示数据
        char buf[20];
        sprintf(buf, "T:%.1f", g_temp);
        oledShowString(0, 0, buf);
        vTaskDelay(1000);  // 1秒
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART1_UART_Init();

    xTaskCreate(SensorTask, "Sensor", 256, NULL, 3, NULL);
    xTaskCreate(DisplayTask, "Display", 256, NULL, 2, NULL);
    vTaskStartScheduler();
}
